    int subtractProductAndSum(int n) {
        string s = to_string(n);
        long long prod = 1;
        int total = 0;
        for (char c : s) {
            int d = c - '0';
            prod *= d;
            total += d;
        }
        return (int)(prod - total);
    }
};

