 * @return {number}
 */
var subtractProductAndSum = function(n) {
    let prod = 1, total = 0;
    while (n > 0) {
        const d = n % 10;
        prod *= d;
        total += d;
        n = Math.floor(n / 10);
    }
    return prod - total;
};
